// Deterministically vary answer positions A–D while keeping them balanced.
// Preserve the original identity of each pictured symbol when options move.
function stableHash(value){let h=2166136261;for(const ch of value){h=Math.imul(h^ch.charCodeAt(0),16777619)}return h>>>0}
const choiceQuestions=missions.flatMap(m=>m.questions).filter(q=>q.type==='choice'||q.type==='drag');
const targetPositions=new Map([...choiceQuestions].sort((a,b)=>stableHash(a.id)-stableHash(b.id)).map((q,i)=>[q.id,(i*3+1)%4]));
choiceQuestions.forEach(q=>{
  const oldKey=q.key,target=targetPositions.get(q.id),correctOption=q.options[oldKey];
  const distractors=q.options.filter((_,i)=>i!==oldKey);
  q.options=[...distractors.slice(0,target),correctOption,...distractors.slice(target)];
  q.key=target;
});
// A compact SVG kit uses Cambridge rectangular resistors. Diagrams are instructional, not measurement scale drawings.
const svg=(body,label)=>'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 460 250" role="img" aria-label="'+label+'" style="max-width:100%;background:#fcfdff"><title>'+label+'</title><g fill="none" stroke="#19354f" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round">'+body+'</g></svg>';
const tx=(x,y,text,size=14)=>'<text x="'+x+'" y="'+y+'" font-size="'+size+'" font-family="Arial, sans-serif" text-anchor="middle" fill="#19354f" stroke="none">'+text+'</text>';
const resistor=(x,y,w=62)=>'<rect x="'+x+'" y="'+(y-12)+'" width="'+w+'" height="24" fill="#fff"/>';
const cell=(x)=>'<path d="M'+x+' 80 V112 M'+x+' 132 V205 M'+(x-19)+' 112 h38 M'+(x-11)+' 132 h22"/>'+tx(x-27,110,'+',12)+tx(x-27,140,'−',12);
