const meter=()=>svg('<path d="M57 70 H157 M219 70 H400 V113 M400 153 V205 H57"/>'+cell(57)+resistor(157,70)+tx(188,58,'R')+'<circle cx="400" cy="133" r="20" fill="#fff"/>'+tx(400,138,'A',17)+'<path d="M157 70 V32 H168 M208 32 H219 V70"/><circle cx="188" cy="32" r="20" fill="#fff"/>'+tx(188,37,'V',16),'Ammeter in series, voltmeter in parallel across a resistor');
const drawSymbol=(kind,x,y)=>{const base='<path d="M'+(x-52)+' '+y+' H'+(x-20)+' M'+(x+20)+' '+y+' H'+(x+52)+'"/>';
if(kind==='lamp')return base+'<circle cx="'+x+'" cy="'+y+'" r="20"/><path d="M'+(x-14)+' '+(y-14)+' l28 28 m0 -28 l-28 28"/>';
if(kind==='resistor')return '<path d="M'+(x-52)+' '+y+' H'+(x-22)+' M'+(x+22)+' '+y+' H'+(x+52)+'"/><rect x="'+(x-22)+'" y="'+(y-13)+'" width="44" height="26"/>';
if(kind==='cell')return '<path d="M'+(x-52)+' '+y+' H'+(x-5)+' M'+(x+5)+' '+y+' H'+(x+52)+' M'+(x-5)+' '+(y-24)+' V'+(y+24)+' M'+(x+5)+' '+(y-15)+' V'+(y+15)+'"/>';
if(kind==='switch')return '<path d="M'+(x-52)+' '+y+' H'+(x-20)+' M'+(x+20)+' '+y+' H'+(x+52)+' M'+(x-18)+' '+(y-3)+' L'+(x+13)+' '+(y-21)+'"/><circle cx="'+(x-20)+'" cy="'+y+'" r="3"/><circle cx="'+(x+20)+'" cy="'+y+'" r="3"/>';
const letter=kind==='ammeter'?'A':kind==='voltmeter'?'V':'M';
return base+'<circle cx="'+x+'" cy="'+y+'" r="20"/>'+tx(x,y+6,letter,18);
};
