CLOZE_DATA.relay={
 en:['When current passes through the control coil of a relay, the coil acts as an ',' and attracts an iron armature. The movement can close ',' in a separate load circuit. The coil circuit may use a relatively ',' current compared with the motor circuit.'],
 th:['เมื่อกระแสผ่านขดลวดควบคุมของรีเลย์ ขดลวดทำหน้าที่เป็น','และดึงอาร์มาเจอร์เหล็ก ทำให้','ในวงจรโหลดอีกชุดปิดลง วงจรขดลวดอาจใช้กระแสค่อนข้าง','เมื่อเทียบกับวงจรมอเตอร์'],
 answers:['electromagnet','contacts','small'],
 bank:[{id:'electromagnet',en:'electromagnet',th:'แม่เหล็กไฟฟ้า'},{id:'contacts',en:'contacts',th:'หน้าสัมผัส'},{id:'small',en:'small',th:'ต่ำ'},{id:'transformer',en:'transformer',th:'หม้อแปลง'},{id:'resistor',en:'resistor',th:'ตัวต้านทาน'},{id:'battery',en:'battery',th:'แบตเตอรี่'},{id:'large',en:'large',th:'สูง'},{id:'open',en:'open',th:'เปิด'},{id:'current',en:'current',th:'กระแส'},{id:'potential',en:'potential difference',th:'ความต่างศักย์'},{id:'fuse',en:'fuse',th:'ฟิวส์'},{id:'diode',en:'diode',th:'ไดโอด'},{id:'parallel',en:'parallel',th:'ขนาน'},{id:'heat',en:'heat',th:'ความร้อน'},{id:'insulator',en:'insulator',th:'ฉนวน'}],
 why:[L('The energised coil produces the magnetic field that moves the armature.','ขดลวดมีกระแสจะสร้างสนามแม่เหล็กดึงอาร์มาเจอร์'),L('The armature moves the switch contacts in the separate load circuit.','อาร์มาเจอร์ทำให้หน้าสัมผัสสวิตช์ในวงจรโหลดเคลื่อน'),L('A small control current can switch a higher-current load without flowing through the sensor.','กระแสต่ำในวงจรควบคุมสามารถสวิตช์โหลดกระแสสูงกว่าโดยไม่ผ่านเซนเซอร์')]
};

const clozeState={key:null,selected:null,filled:[null,null,null],checked:false,stage:'fill'};
function resetCloze(){
 clozeState.key=null;clozeState.selected=null;clozeState.filled=[null,null,null];
 clozeState.checked=false;clozeState.stage='fill';
}
function syncCloze(m){
 const key=m.id+'|'+state.scope+'|'+state.tier;
 if(clozeState.key!==key){resetCloze();clozeState.key=key}
}
function clozeIsDone(){return clozeState.stage==='done'}
function renderCloze(m){
 syncCloze(m);
 const c=CLOZE_DATA[m.id];
 if(!c)throw Error('Missing knowledge recall for mission '+m.id);
 const active=!clozeIsDone(),panel=$('clozeGate');
 document.querySelector('.workspace').classList.toggle('cloze-active',active);
 panel.hidden=!active;
 if(!active){panel.innerHTML='';return}
 const labels=Object.fromEntries(c.bank.map(word=>[word.id,word]));
 const renderParagraph=(pieces,language)=>'<p class="cloze-passage cloze-lang-'+language+'" lang="'+language+'">'+pieces.map((part,i)=>{
   const id=clozeState.filled[i],word=id&&labels[id],isCorrect=id===c.answers[i];
   const gap=i<3?'<button type="button" class="cloze-blank '+(word?'filled ':'')+(clozeState.checked?(isCorrect?'correct':'incorrect'):'')+'" data-gap="'+i+'" aria-label="Blank '+(i+1)+'" title="'+(language==='th'?'แตะช่องเพื่อเติมหรือเอาคำออก':'Tap to fill or clear')+'">'+(word?esc(word[language]):'['+(i+1)+'] __________')+'</button>':'';
   return esc(part)+gap
 }).join('')+'</p>';
 const ordered=c.bank.slice().sort((a,b)=>stableHash(m.id+'-'+a.id)-stableHash(m.id+'-'+b.id));
 const tokens=ordered.map(w=>{
   const used=clozeState.filled.includes(w.id),selected=clozeState.selected===w.id;
   return '<button type="button" class="cloze-token '+(selected?'selected':'')+'" data-token="'+esc(w.id)+'" draggable="'+(!used&&clozeState.stage==='fill')+'" aria-pressed="'+selected+'" '+(used||clozeState.stage!=='fill'?'disabled':'')+'>'+dual(L(w.en,w.th))+'</button>'
 }).join('');
 const right=clozeState.filled.filter((id,i)=>id===c.answers[i]).length;
 const explanations=clozeState.checked?'<div class="cloze-feedback '+(right===3?'success':'')+'" role="status" aria-live="polite"><strong>'+dual(L(right===3?'✓ All three terms are correct.':'Review the marked blanks and try again.',right===3?'✓ เติมถูกครบทั้งสามช่องแล้ว':'ตรวจช่องที่ยังผิดแล้วลองอีกครั้ง'))+' ('+right+'/3)</strong>'+c.why.map((why,i)=>'<p><strong>'+(i+1)+'.</strong> '+dual(why)+'</p>').join('')+'</div>':'';
 const header='<div class="cloze-title"><div><span class="cloze-kicker">STEP 01 · ACADEMIC CLOZE / บทความวิชาการเติมคำ</span><h3>'+dual(L('Recall before you practise','ทบทวนความรู้ก่อนทำข้อสอบ'))+'</h3></div><span class="tier-badge">'+esc(m.code)+'</span></div>';
 const controls=clozeState.stage==='ready'?'<button type="button" class="primary" id="clozeContinue">'+dual(L('Continue to practice questions →','เข้าสู่โจทย์ฝึก →'))+'</button>':'<button type="button" class="primary" id="clozeCheck">'+dual(L('Check all blanks','ตรวจคำตอบทั้งบทความ'))+'</button><button type="button" id="clozeClear" class="quiet">'+dual(L('Clear blanks','ล้างช่องคำตอบ'))+'</button>';
 panel.innerHTML=header+'<p class="cloze-hint">'+dual(L('Read the accompanying article. Drag a word into each blank, or tap a word and then the blank on iPad. Every mission begins with this review.','อ่านบทความทบทวนด้านข้าง แล้วลากคำลงในช่องว่าง หรือแตะคำแล้วแตะช่องบน iPad ทุกภารกิจจะเริ่มด้วยการทบทวนนี้'))+'</p>'+renderParagraph(c.en,'en')+renderParagraph(c.th,'th')+'<p class="cloze-bank-label">WORD BANK · 15 '+dual(L('terms (3 answers + 12 distractors)','คำ (คำตอบ 3 + คำหลอก 12)'))+'</p><div class="cloze-bank" role="group" aria-label="Knowledge recall word bank">'+tokens+'</div><p class="cloze-note">'+dual(L('One word per blank. Tap a filled blank to clear it.','ใช้หนึ่งคำต่อหนึ่งช่อง แตะช่องที่เติมแล้วเพื่อลบคำ'))+'</p>'+explanations+'<div class="cloze-actions">'+controls+'</div>';
 const setGap=(i,id)=>{
   if(clozeState.stage!=='fill'||!Number.isInteger(i)||i<0||i>=3||!labels[id])return;
   clozeState.filled=clozeState.filled.map(value=>value===id?null:value);
   clozeState.filled[i]=id;clozeState.selected=null;clozeState.checked=false;
   renderCloze(m);
 };
 panel.querySelectorAll('[data-token]').forEach(el=>{
   el.onclick=()=>{if(clozeState.stage!=='fill')return;clozeState.selected=el.dataset.token;renderCloze(m)};
   el.addEventListener('dragstart',ev=>{if(clozeState.stage==='fill')ev.dataTransfer.setData('text/plain',el.dataset.token)});
 });
 panel.querySelectorAll('[data-gap]').forEach(el=>{
   const index=Number(el.dataset.gap);
   el.onclick=()=>{
     if(clozeState.stage!=='fill')return;
     if(clozeState.selected)setGap(index,clozeState.selected);
     else if(clozeState.filled[index]){clozeState.filled[index]=null;clozeState.checked=false;renderCloze(m)}
   };
   el.addEventListener('dragover',ev=>{if(clozeState.stage!=='fill')return;ev.preventDefault();el.classList.add('over')});
   el.addEventListener('dragleave',()=>el.classList.remove('over'));
   el.addEventListener('drop',ev=>{ev.preventDefault();el.classList.remove('over');setGap(index,ev.dataTransfer.getData('text/plain'))});
 });
 const check=$('clozeCheck');
 if(check)check.onclick=()=>{
   if(clozeState.filled.some(x=>!x)){alert(state.lang==='th'?'เติมคำให้ครบทั้ง 3 ช่องก่อนตรวจ':'Fill all three blanks before checking.');return}
   clozeState.checked=true;
   if(clozeState.filled.every((id,i)=>id===c.answers[i]))clozeState.stage='ready';
   renderCloze(m);
 };
 const clear=$('clozeClear');
 if(clear)clear.onclick=()=>{clozeState.selected=null;clozeState.filled=[null,null,null];clozeState.checked=false;renderCloze(m)};
 const next=$('clozeContinue');
 if(next)next.onclick=()=>{clozeState.stage='done';render();$('questionTitle').focus()};
}

