try{const old=JSON.parse(localStorage.getItem(STORAGE)||'null');if(old&&typeof old==='object'){state={...state,...old,answers:old.answers||{},checked:old.checked||{},reviewed:old.reviewed||{},known:old.known||{}}}}catch(_){}
